insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('903eec0c-0b09-5c2f-a4b9-4fa0b02003f4', 'Catedral arquidiocesana desde 2016; Missionários Redentoristas. O a12.com bloqueia robôs: horários pelo resumo da busca das páginas oficiais. Confissões diárias existem; só as do fim de semana vieram com hora. Ponto no mapa aproximado: centro da cidade.', '{"https://www.a12.com/santuario/missa/pastoral-horarios-de-missa-santuario-nacional","https://www.a12.com/area-do-devoto/central-de-ajuda/contato","https://www.a12.com/redacaoa12/santuarionacional/veja-a-programacao-deste-fim-de-semana-no-santuario-nacional"}', 'media'),
  ('d670668a-c30b-5138-878b-d2b8458b6928', 'Criado em 08/12/2010, aos cuidados dos Franciscanos. Sem missa às 7h na quarta-feira; confissões não acontecem na quarta. Fora do formato: Novena Perpétua de Frei Galvão todos os dias às 14h40; Novena de Frei Galvão de 17 a 25 de cada mês às 20h40 nas redes sociais', '{"https://santuariofreigalvao.com/santuario/horarios","https://santuariofreigalvao.com/"}', 'alta'),
  ('2e4fd881-5397-5f55-8b48-c9697faad9df', 'Criada em 1998.', '{"https://arqaparecida.org.br/paroquia/22407-santo-afonso-maria-de-ligorio/missas","https://arqaparecida.org.br/paroquia/22407-santo-afonso-maria-de-ligorio","https://arqaparecida.org.br/paroquia/22407-santo-afonso-maria-de-ligorio/comunidades"}', 'alta'),
  ('8735e2f6-b916-58e1-973c-34b03afe0e90', 'Criada em 1994. Sem horário no site da arquidiocese (Horário de Missas vazio); sem outra fonte oficial encontrada.', '{"https://arqaparecida.org.br/paroquia/58d9d-sao-roque","https://arqaparecida.org.br/paroquia/58d9d-sao-roque/comunidades"}', ''),
  ('835f43ee-8567-5623-94d9-2f0e176eee4b', 'Criada em 18/11/1893. Horário da matriz pelo site da paróquia, mais novo que o da arquidiocese (que dá sábado 16h e domingo 18h). Ponto no mapa aproximado: centro da cidade.', '{"https://paroquiadeaparecida.com.br/","https://arqaparecida.org.br/paroquia/ce090-nossa-senhora-da-conceicao-aparecida-e-sao-benedito/missas","https://arqaparecida.org.br/paroquia/ce090-nossa-senhora-da-conceicao-aparecida-e-sao-benedito","https://arqaparecida.org.br/paroquia/ce090-nossa-senhora-da-conceicao-aparecida-e-sao-benedito/comunidades"}', 'alta'),
  ('da5d72b9-ff6e-5785-9b49-92ca45fba639', 'Criada em 25/02/1651; foi a catedral da arquidiocese de 1996 a 2016. A comunidade N. S. das Graças é o Convento das Franciscanas da Terceira Ordem Seráfica. Sem horário no site da arquidiocese (Horário de Missas vazio); sem outra fonte oficial encontrada.', '{"https://arqaparecida.org.br/paroquia/b45cd-santo-antonio","https://arqaparecida.org.br/paroquia/b45cd-santo-antonio/comunidades"}', ''),
  ('9c544ba1-d452-524a-9b6e-89a4fa0aad62', 'Criada em 08/12/1959.', '{"https://arqaparecida.org.br/paroquia/3e53e-nossa-senhora-da-gloria/missas","https://arqaparecida.org.br/paroquia/3e53e-nossa-senhora-da-gloria","https://arqaparecida.org.br/paroquia/3e53e-nossa-senhora-da-gloria/comunidades"}', 'alta'),
  ('6a0cb305-26c6-5501-abee-2f1dc6446244', 'Criada em 07/12/2003. Sem horário no site da arquidiocese (Horário de Missas vazio); sem outra fonte oficial encontrada. Ponto no mapa aproximado: centro da cidade.', '{"https://arqaparecida.org.br/paroquia/02894-nossa-senhora-das-gracas","https://arqaparecida.org.br/paroquia/02894-nossa-senhora-das-gracas/comunidades"}', ''),
  ('fc5f5790-2873-5586-ae43-734deaad31d8', 'Criada em 1991.', '{"https://arqaparecida.org.br/paroquia/b7bdf-nossa-senhora-de-fatima/missas","https://arqaparecida.org.br/paroquia/b7bdf-nossa-senhora-de-fatima","https://arqaparecida.org.br/paroquia/b7bdf-nossa-senhora-de-fatima/comunidades"}', 'alta'),
  ('ca9731fc-1edc-547e-af95-1be1ea9c7ceb', 'Criada em 1991. Sem horário no site da arquidiocese (Horário de Missas vazio); sem outra fonte oficial encontrada.', '{"https://arqaparecida.org.br/paroquia/39b99-nossa-senhora-de-lourdes","https://arqaparecida.org.br/paroquia/39b99-nossa-senhora-de-lourdes/comunidades"}', ''),
  ('cbbe581e-6f52-52a8-8939-a8e01cda8b8a', 'Criada em 13/02/1996. Sem horário no site da arquidiocese (Horário de Missas vazio); sem outra fonte oficial encontrada.', '{"https://arqaparecida.org.br/paroquia/54009-nossa-senhora-do-rosario","https://arqaparecida.org.br/paroquia/54009-nossa-senhora-do-rosario/comunidades"}', ''),
  ('82ec0330-e12e-501a-bedb-1a92df513154', 'Criada em 28/08/1928. Sem horário no site da arquidiocese (Horário de Missas vazio); sem outra fonte oficial encontrada.', '{"https://arqaparecida.org.br/paroquia/7df0e-purissimo-coracao-de-maria","https://arqaparecida.org.br/paroquia/7df0e-purissimo-coracao-de-maria/comunidades"}', ''),
  ('23b038d4-c22a-519e-9d54-112c3a23c121', 'Criada em 23/09/2021, a paróquia mais nova da arquidiocese.', '{"https://arqaparecida.org.br/paroquia/bdc6a-santa-luzia/missas","https://arqaparecida.org.br/paroquia/bdc6a-santa-luzia","https://arqaparecida.org.br/paroquia/bdc6a-santa-luzia/comunidades"}', 'alta'),
  ('42ca39ac-6dff-5813-a5b4-a78563d5a002', 'Criada em 02/01/1998. Ponto no mapa aproximado: centro da cidade.', '{"https://arqaparecida.org.br/paroquia/c39e0-santo-expedito/missas","https://arqaparecida.org.br/paroquia/c39e0-santo-expedito","https://arqaparecida.org.br/paroquia/c39e0-santo-expedito/comunidades"}', 'alta'),
  ('1098cac0-259b-5168-a78c-bae474a83045', 'Criada em 01/05/2005. Sem horário no site da arquidiocese (Horário de Missas vazio); sem outra fonte oficial encontrada. Ponto no mapa aproximado: centro da cidade.', '{"https://arqaparecida.org.br/paroquia/36e28-sao-dimas","https://arqaparecida.org.br/paroquia/36e28-sao-dimas/comunidades"}', ''),
  ('0abd62c3-5ed6-5318-b64c-2cf8a79be36a', 'Criada em 1991.', '{"https://arqaparecida.org.br/paroquia/c88eb-sao-francisco-de-assis/missas","https://arqaparecida.org.br/paroquia/c88eb-sao-francisco-de-assis","https://arqaparecida.org.br/paroquia/c88eb-sao-francisco-de-assis/comunidades"}', 'alta'),
  ('b7c4a777-bb4e-5ded-9aac-86161ba9d411', 'Criada em dezembro de 2009.', '{"https://arqaparecida.org.br/paroquia/e796f-sao-miguel-arcanjo/missas","https://arqaparecida.org.br/paroquia/e796f-sao-miguel-arcanjo","https://arqaparecida.org.br/paroquia/e796f-sao-miguel-arcanjo/comunidades"}', 'alta'),
  ('18dbf4d4-92f7-5b26-a6b0-a6a5a543892b', 'Criada em 07/09/1972. O site próprio da paróquia estava fora do ar em 13/11/2026.', '{"https://arqaparecida.org.br/paroquia/b778b-sao-pedro-apostolo/missas","https://arqaparecida.org.br/paroquia/b778b-sao-pedro-apostolo","https://arqaparecida.org.br/paroquia/b778b-sao-pedro-apostolo/comunidades"}', 'alta'),
  ('8e653879-9123-5594-91d7-c5d8b974d5ef', 'Criada em 25/04/1880. Ponto no mapa aproximado: centro da cidade.', '{"https://arqaparecida.org.br/paroquia/44ead-nossa-senhora-da-conceicao/missas","https://arqaparecida.org.br/paroquia/44ead-nossa-senhora-da-conceicao","https://arqaparecida.org.br/paroquia/44ead-nossa-senhora-da-conceicao/comunidades"}', 'alta'),
  ('6bbaeb0c-acfb-58e6-8184-cab0619ba134', 'Criada em 30/11/1976. Sem horário no site da arquidiocese (Horário de Missas vazio); sem outra fonte oficial encontrada.', '{"https://arqaparecida.org.br/paroquia/ea1d6-senhor-bom-jesus","https://arqaparecida.org.br/paroquia/ea1d6-senhor-bom-jesus/comunidades"}', ''),
  ('fdd3dcea-d1de-55a4-ba7e-e564981eb19c', 'Criada em 29/01/1910. Sem horário no site da arquidiocese (Horário de Missas vazio); sem outra fonte oficial encontrada. Ponto no mapa aproximado: centro da cidade.', '{"https://arqaparecida.org.br/paroquia/2336a-santana","https://arqaparecida.org.br/paroquia/2336a-santana/comunidades"}', ''),
  ('d122f0fb-a097-53b3-a6c2-e3afdb2922d3', 'O Convento Santa Clara e a Missão Sede Santos pertencem ao território da paróquia, diz a página da Catedral.', '{"https://diocesedetaubate.org.br/catedral/","https://diocesedetaubate.org.br/paroquias/"}', 'alta'),
  ('fc4718a8-ccb7-50ee-bd07-3ca89aa5522d', 'A matriz é o Santuário de Santa Teresinha, o primeiro do mundo dedicado a ela. Tem também a Comunidade São João Batista.', '{"https://diocesedetaubate.org.br/santateresinha/","https://diocesedetaubate.org.br/paroquias/"}', 'alta'),
  ('c44979a7-6cf7-5807-a048-c4faec2e26e8', 'Tem as comunidades Imaculada Conceição, Cristo Redentor e São Judas Tadeu, sem horário publicado. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedetaubate.org.br/saopedro/","https://diocesedetaubate.org.br/paroquias/"}', 'alta'),
