  ('71ef31c7-de53-5d1a-98c6-889cdcc3555b', 'Paróquia do Alto da Ponte; existe outra São Benedito no Residencial Galo Branco. Fora do formato: Confissão na quinta após a missa das 19h30', '{"https://diocese-sjc.org.br/local/paroquia-sao-benedito/","https://diocese-sjc.org.br/local/paroquia-sao-benedito/"}', 'alta'),
  ('5ed209b7-9894-5916-8d60-3f720e5cc334', 'Ponto no mapa aproximado: centro da cidade.', '{"https://diocese-sjc.org.br/local/paroquia-sao-bento/","https://diocese-sjc.org.br/local/paroquia-sao-bento/"}', 'alta'),
  ('febaad8b-1fd9-5f9f-a2fe-ff44e5a948fd', 'Fora do formato: Confissão na quinta após a missa das 19h30', '{"https://diocese-sjc.org.br/local/paroquia-sao-francisco-de-assis/","https://diocese-sjc.org.br/local/paroquia-sao-francisco-de-assis/"}', 'alta'),
